function EspaceEleve({ data, user, activeYear }) {
  const [tab, setTab] = useTabWithHistory("emploi", "eleve");
  const [filtrePeriodId, setFiltrePeriodId] = useState(null);
  const syId = activeYear?.id;
  const TYPE_COLORS = { "Comportement":C.gold, "Situation":C.blue, "Transversal":C.green };
  const ns = filterBySY(data.notes, syId).filter(n=>n.eleveId===user.id);
  const as = filterBySY(data.absences, syId).filter(a=>a.eleveId===user.id);
  const allPeriodsEleve = (data.school_periods||[]).filter(p=>p.school_year_id===syId);
  const periodActiveEleve = allPeriodsEleve.find(p=>p.is_active) || allPeriodsEleve[0] || null;
  const periodSelEleve = allPeriodsEleve.find(p=>p.id===filtrePeriodId) || periodActiveEleve;
  // APC: moyenne calculée dans ModNotes via pourcentage
  const eleveTabs = [{id:"emploi",label:"🗓️ Emploi du temps"},{id:"notes",label:"📋 Mon Bulletin"},{id:"absences",label:"📋 Absences"},{id:"ia",label:"🤖 Tuteur IA"}];
  return (
    <div style={{minHeight:"100vh",background:C.bg}}>
      <Drawer tabs={eleveTabs} active={tab} onSelect={setTab} userName={user.nom} userRole={user.role} roleColor={C.gold} roleLabel="Élève" onLogout={()=>window.__cfpLogout&&window.__cfpLogout()} sy={null} data={null} setData={null} />
      <div style={{padding:"16px 14px",boxSizing:"border-box",width:"100%",overflowX:"hidden"}}>
      {tab==="emploi"&&<ModEmploiDuTemps data={data} setData={()=>{}} canEdit={false} userClasse={user.classe} syId={activeYear?.id} currentUser={user} />}
      {tab==="notes"&&(
        <div>
          {/* Sélecteur période scolaire */}
          {allPeriodsEleve.length === 0 ? (
            <div style={{textAlign:"center",color:C.muted,padding:30,background:C.gold+"12",border:`1px solid ${C.gold}33`,borderRadius:10,marginBottom:14}}>
              ⚠️ Aucune période scolaire n'a encore été créée pour cette année.
            </div>
          ) : (
            <div style={{display:"flex",gap:8,marginBottom:14,flexWrap:"wrap"}}>
              {allPeriodsEleve.map(p=>(
                <button key={p.id} onClick={()=>setFiltrePeriodId(p.id)} style={{flex:"1 1 auto",minWidth:90,padding:"8px 10px",borderRadius:9,border:`2px solid ${(periodSelEleve?.id===p.id)?C.navy:C.border}`,background:(periodSelEleve?.id===p.id)?C.navy:"white",color:(periodSelEleve?.id===p.id)?"white":C.muted,fontWeight:700,fontSize:11,cursor:"pointer",fontFamily:"inherit"}}>
                  {p.label}{p.is_active?" ★":""}
                </button>
              ))}
            </div>
          )}

          {/* Bulletin APC */}
          {allPeriodsEleve.length > 0 && (()=>{
            const classeCode = user.classe_code || "";
            const coursClasse = filterBySY(data.cours||[], syId).filter(c=>c.classe_code===classeCode);
            const notesT = ns.filter(n=>n.period_id===periodSelEleve?.id);
            let totalPts = 0, totalPct = 0;
            coursClasse.forEach(c=>{
              const n = notesT.find(n=>n.matiere===c.module);
              if(n){ totalPts += (+n.note||0)*(+c.pourcentage/100); totalPct += +c.pourcentage; }
            });
            const moyenne = totalPct>0 ? Math.round(totalPts*10)/10 : null;
            const getMention = m=>{ if(m===null)return{label:"—",color:C.muted}; if(m>=80)return{label:"Très Bien",color:C.green}; if(m>=70)return{label:"Bien",color:"#059669"}; if(m>=60)return{label:"Assez Bien",color:C.gold}; if(m>=50)return{label:"Passable",color:C.gold}; return{label:"Insuffisant",color:C.red}; };
            const mention = getMention(moyenne);
            return (
              <div>
                {/* En-tête bulletin */}
                <div style={{background:`linear-gradient(135deg,${C.navy},#2C5282)`,borderRadius:14,padding:"16px 18px",marginBottom:16,color:"white"}}>
                  <div style={{fontWeight:900,fontSize:16,marginBottom:2}}>🎓 {user.nom}</div>
                  <div style={{opacity:0.75,fontSize:12,marginBottom:10}}>{user.classe} • {periodSelEleve?.label||"—"}</div>
                  <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10}}>
                    <div style={{background:"rgba(255,255,255,0.15)",borderRadius:10,padding:"10px 12px",textAlign:"center"}}>
                      <div style={{fontSize:28,fontWeight:900,color:mention.color==="white"?"#FCD34D":moyenne>=50?"#6EE7B7":"#FCA5A5"}}>{moyenne!==null?moyenne:"—"}</div>
                      <div style={{fontSize:10,opacity:0.8}}>Moyenne /100</div>
                    </div>
                    <div style={{background:"rgba(255,255,255,0.15)",borderRadius:10,padding:"10px 12px",textAlign:"center"}}>
                      <div style={{fontSize:18,fontWeight:900,color:"white"}}>{mention.label}</div>
                      <div style={{fontSize:10,opacity:0.8}}>Mention</div>
                    </div>
                  </div>
                  {moyenne!==null&&<div style={{marginTop:10,height:6,background:"rgba(255,255,255,0.2)",borderRadius:3}}>
                    <div style={{width:`${moyenne}%`,height:"100%",background:"white",borderRadius:3,transition:"width 0.3s"}} />
                  </div>}
                </div>

                {/* Tableau des modules */}
                {coursClasse.length===0 && <div style={{textAlign:"center",color:C.muted,padding:30}}>Aucun module pour votre classe</div>}
                <div style={{display:"grid",gap:8}}>
                  {coursClasse.map(c=>{
                    const note = notesT.find(n=>n.matiere===c.module);
                    const pts = note ? Math.round((+note.note||0)*(+c.pourcentage/100)*10)/10 : null;
                    const couleur = !note?C.muted:+note.note>=70?C.green:+note.note>=50?C.gold:C.red;
                    return (
                      <div key={c.id} style={{background:C.card,border:`1px solid ${note?couleur+"44":C.border}`,borderRadius:11,padding:"12px 14px"}}>
                        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:4}}>
                          <div style={{fontWeight:700,color:C.navy,fontSize:13,flex:1,minWidth:0,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{c.module}</div>
                          <div style={{fontWeight:900,fontSize:18,color:couleur,marginLeft:8,flexShrink:0}}>
                            {note ? note.note : <span style={{color:C.muted,fontSize:13}}>—</span>}
                            {note && <span style={{fontSize:10,color:C.muted}}>/100</span>}
                          </div>
                        </div>
                        <div style={{display:"flex",justifyContent:"space-between",fontSize:11,color:C.muted}}>
                          <span>👨‍🏫 {c.enseignant}</span>
                          <span style={{display:"flex",gap:8}}>
                            <span style={{color:C.gold,fontWeight:700}}>{c.pourcentage}%</span>
                            {pts!==null&&<span style={{color:C.navy,fontWeight:700}}>→ {pts} pts</span>}
                          </span>
                        </div>
                        {note&&<div style={{marginTop:6,height:4,background:C.border,borderRadius:2}}>
                          <div style={{width:`${note.note}%`,height:"100%",background:couleur,borderRadius:2}} />
                        </div>}
                        <Badge color={TYPE_COLORS[c.type]||C.navy}>{c.type}</Badge>
                      </div>
                    );
                  })}
                </div>
              </div>
            );
          })()}
        </div>
      )}

      {tab==="absences"&&(
        <div>
          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:12,marginBottom:16}}>
            <StatCard icon="📋" label="Total absences" value={as.length} color={C.blue} />
            <StatCard icon="⚠️" label="Non justifiées" value={as.filter(a=>!a.justifie).length} color={C.red} />
          </div>
          {as.map(a=><div key={a.id} style={{background:C.card,border:`1px solid ${a.justifie?C.border:C.red+"55"}`,borderRadius:11,padding:"12px 16px",display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:8}}>
            <div><div style={{fontWeight:600,color:C.text,fontSize:13}}>{a.date}</div><div style={{fontSize:11,color:C.muted}}>{a.motif||"Motif non renseigné"}</div></div>
            <Badge color={a.justifie?C.green:C.red}>{a.justifie?"Justifiée":"Non justifiée"}</Badge>
          </div>)}
          {as.length===0&&<div style={{textAlign:"center",color:C.muted,padding:50}}>Aucune absence 🎉</div>}
        </div>
      )}
      {tab==="ia"&&<ModIA role="eleve" userName={user.nom.split(" ")[0]} />}
      </div>
    </div>
  );
}

function EspaceParent({ data, setData, user, activeYear }) {
  const [tab, setTab] = useTabWithHistory("suivi", "parent");
  const [selStudentId, setSelStudentId] = useState(null);

  const syId = activeYear?.id;

  // ── Relation normalisée : parent_student pivot ─────────────────────────────
  const pivot = (data.parent_student || []).filter(r => r.parent_id === user.id);
  const mesEnfants = pivot.map(r => {
    const eleve = data.users.find(u => u.id === r.student_id && u.role === "eleve");
    return eleve ? { ...eleve, relation_type: r.relation_type } : null;
  }).filter(Boolean);

  // Fallback: support ancien format "enfant" (string)
  const enfantFallback = mesEnfants.length === 0 && user.enfant
    ? data.users.filter(u => u.role === "eleve" && u.nom === user.enfant)
    : [];
  const tousEnfants = mesEnfants.length > 0 ? mesEnfants : enfantFallback;

  const enfant = tousEnfants.find(e => e.id === selStudentId) || tousEnfants[0] || null;

  const ns = enfant ? filterBySY(data.notes, syId).filter(n => n.eleveId === enfant.id) : [];
  const as = enfant ? filterBySY(data.absences, syId).filter(a => a.eleveId === enfant.id) : [];

  return (
    <div>
      <Drawer
        tabs={[
          { id: "suivi",    label: "👁️ Suivi enfant" },
          { id: "messages", label: "💬 Messages" },
          { id: "ia",       label: "🤖 Conseiller IA" },
        ]}
        active={tab}
        onSelect={setTab}
        userName={user.nom}
        userRole={user.role}
        roleColor="#2ECC71"
        roleLabel="Parent"
        onLogout={() => window.__cfpLogout?.()}
      />
      <div style={{ padding: "16px 14px", boxSizing: "border-box" }}>

        {/* Sélecteur enfant si plusieurs */}
        {tousEnfants.length > 1 && (
          <div style={{ marginBottom: 14 }}>
            <label style={{ fontSize: 11, fontWeight: 700, color: C.muted, textTransform: "uppercase", letterSpacing: 1, display: "block", marginBottom: 6 }}>
              👶 Sélectionner un enfant
            </label>
            <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
              {tousEnfants.map(e => (
                <button key={e.id} onClick={() => setSelStudentId(e.id)}
                  style={{ padding: "8px 14px", borderRadius: 9, border: `2px solid ${enfant?.id === e.id ? C.navy : C.border}`, background: enfant?.id === e.id ? C.navy : "white", color: enfant?.id === e.id ? "white" : C.text, fontWeight: 700, fontSize: 12, cursor: "pointer", fontFamily: "inherit" }}>
                  🎓 {e.nom} <span style={{ fontSize: 10, opacity: 0.7 }}>({e.classe})</span>
                </button>
              ))}
            </div>
          </div>
        )}

        {tousEnfants.length === 0 && (
          <div style={{ textAlign: "center", padding: 40, color: C.muted }}>
            <div style={{ fontSize: 40, marginBottom: 10 }}>🔍</div>
            <div>Aucun enfant associé à votre compte.</div>
            <div style={{ fontSize: 12, marginTop: 6 }}>Contactez le secrétariat du CFP.</div>
          </div>
        )}

        {tab === "suivi" && enfant && (
          <div>
            {/* Fiche enfant */}
            <div style={{ background: `linear-gradient(135deg,${C.navy},#2C5282)`, borderRadius: 14, padding: "14px 16px", marginBottom: 16, color: "white" }}>
              <div style={{ fontWeight: 900, fontSize: 15, marginBottom: 2 }}>🎓 {enfant.nom}</div>
              <div style={{ fontSize: 11, opacity: 0.75 }}>{enfant.filiere} • {enfant.classe}</div>
              {enfant.matricule && <div style={{ fontSize: 10, opacity: 0.6, marginTop: 2 }}>Matricule : {enfant.matricule}</div>}
              {enfant.relation_type && <div style={{ fontSize: 10, opacity: 0.6 }}>Relation : {enfant.relation_type}</div>}
            </div>

            {/* Stats */}
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10, marginBottom: 16 }}>
              <StatCard icon="📝" label="Notes saisies" value={ns.length} color={C.blue} />
              <StatCard icon="📋" label="Absences" value={as.length} color={C.red} />
            </div>

            {/* Notes */}
            {ns.length > 0 && (
              <Card style={{ marginBottom: 14 }}>
                <div style={{ fontWeight: 800, color: C.navy, fontSize: 13, marginBottom: 10 }}>📝 Dernières notes</div>
                {ns.slice(-5).reverse().map((n, i) => (
                  <div key={i} style={{ display: "flex", justifyContent: "space-between", padding: "7px 0", borderBottom: `1px solid ${C.border}`, fontSize: 13 }}>
                    <span style={{ color: C.text }}>{n.matiere}</span>
                    <span style={{ fontWeight: 800, color: +n.note >= 50 ? C.green : C.red }}>{n.note}/100</span>
                  </div>
                ))}
              </Card>
            )}

            {/* Absences */}
            {as.length > 0 && (
              <Card>
                <div style={{ fontWeight: 800, color: C.navy, fontSize: 13, marginBottom: 10 }}>📋 Dernières absences</div>
                {as.slice(-5).reverse().map((a, i) => (
                  <div key={i} style={{ display: "flex", justifyContent: "space-between", padding: "7px 0", borderBottom: `1px solid ${C.border}`, fontSize: 13 }}>
                    <div>
                      <div style={{ color: C.text }}>{a.date}</div>
                      <div style={{ fontSize: 11, color: C.muted }}>{a.justification || "Non renseigné"}</div>
                    </div>
                    <Badge color={a.justifie ? C.green : C.red}>{a.justifie ? "Justifiée" : "Non just."}</Badge>
                  </div>
                ))}
              </Card>
            )}
          </div>
        )}

        {tab === "messages" && <ModMessages data={data} setData={setData} user={user} canManage={false} />}
        {tab === "ia" && <ModIA role="parent" userName={user.nom.split(" ").slice(-1)[0]} />}
      </div>
    </div>
  );
}



// ─── ESPACE ADMIN ─────────────────────────────────────────────────────────────
function EspaceAdmin({ data, setData, onLogout }) {
  const [tab, setTab] = useTabWithHistory("comptes", "admin");
  const [modal, setModal] = useState(null);
  const [form, setForm] = useState({});
  const [confirm, setConfirm] = useState(null);
  const [resetTarget, setResetTarget] = useState(null);
  const [newPwdInput, setNewPwdInput] = useState("");

  const roleColors = {
    direction:"#1E3A5F", directeur_etudes:"#1A6B8A", charge_stages:"#7D3C98",
    charge_travaux:"#1A6B4A", charge_finances:"#C0392B", conseiller:"#D35400",
    secretaire:"#0E6655", enseignant:"#2471A3", eleve:"#C8960C", parent:"#2ECC71"
  };
  const roleLabels = {
    direction:"Direction", directeur_etudes:"Dir. Études", charge_stages:"Ch. Stages",
    charge_travaux:"Ch. Travaux", charge_finances:"Ch. Finances", conseiller:"Conseiller",
    secretaire:"Secrétaire", enseignant:"Enseignant", eleve:"Élève", parent:"Parent"
  };

  const allUsers = data.users.filter(u => u.role !== "admin");
  const actifs = allUsers.filter(u => u.actif).length;
  const bloques = allUsers.filter(u => !u.actif).length;

  const openEdit = u => { setForm({...u}); setModal("edit"); };
  const openAdd  = () => { setForm({login:"",password:"",nom:"",role:"enseignant",poste:"",actif:true}); setModal("add"); };

  const save = () => {
    if (!form.login || !form.password || !form.nom) return;
    const upd = form.id
      ? data.users.map(u => u.id === form.id ? form : u)
      : [...data.users, {...form, id: Date.now()}];
    setData({...data, users: upd});
    setModal(null);
  };

  const toggle = id => setData({...data, users: data.users.map(u => u.id===id ? {...u, actif:!u.actif} : u)});
  const del    = id => { setData({...data, users: data.users.filter(u => u.id !== id)}); setConfirm(null); };
  const resetPwd = id => { const u = data.users.find(x=>x.id===id); setResetTarget(u); setNewPwdInput(u?.password||""); };
  const confirmResetPwd = () => {
    if (!newPwdInput.trim() || !resetTarget) return;
    setData({...data, users: data.users.map(u => u.id===resetTarget.id ? {...u, password:newPwdInput.trim()} : u)});
    setResetTarget(null);
  };

  const roleOpts = ["direction","directeur_etudes","charge_stages","charge_travaux",
                    "charge_finances","conseiller","secretaire","enseignant","eleve","parent"]
                    .map(r => ({value:r, label:roleLabels[r]}));

  return (
    <div style={{minHeight:"100vh",background:"#0D0D1A",fontFamily:"'Segoe UI',sans-serif",overflowX:"hidden",maxWidth:"100vw",boxSizing:"border-box"}}>
      <div style={{background:"linear-gradient(135deg,#1E0A3C,#4C1D95)",padding:"10px 14px",display:"flex",alignItems:"center",gap:10,boxShadow:"0 2px 20px rgba(0,0,0,0.5)",position:"sticky",top:0,zIndex:100}}>
        <span style={{fontSize:20,flexShrink:0}}>🛡️</span>
        <div style={{flex:1,minWidth:0}}>
          <div style={{color:"#C4B5FD",fontSize:8,fontWeight:800,letterSpacing:1,textTransform:"uppercase"}}>CFP Lambanyi — Admin</div>
          <div style={{color:"white",fontWeight:900,fontSize:13}}>Panneau de Contrôle</div>
        </div>
        <button onClick={onLogout} style={{background:"#3B0A0A",border:"1px solid #DC2626",color:"#FCA5A5",borderRadius:8,padding:"6px 11px",fontSize:11,cursor:"pointer",fontFamily:"inherit",fontWeight:700}}>🔓 Déco.</button>
      </div>

      <div style={{padding:"14px 12px",boxSizing:"border-box",width:"100%"}}>
        {/* Stats */}
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10,marginBottom:16}}>
          {[
            {icon:"👥",label:"Total comptes",value:allUsers.length,color:"#7C3AED"},
            {icon:"✅",label:"Actifs",value:actifs,color:"#059669"},
            {icon:"🚫",label:"Bloqués",value:bloques,color:"#DC2626"},
            {icon:"📚",label:"Filières",value:data.filieres?.length||0,color:"#D97706"},
          ].map((s,i)=>(
            <div key={i} style={{background:"#1A0A2E",border:"1px solid #2D1B69",borderLeft:`4px solid ${s.color}`,borderRadius:10,padding:"10px 12px",display:"flex",alignItems:"center",gap:8,boxSizing:"border-box"}}>
              <span style={{fontSize:22,flexShrink:0}}>{s.icon}</span>
              <div style={{minWidth:0}}>
                <div style={{fontSize:18,fontWeight:900,color:s.color}}>{s.value}</div>
                <div style={{fontSize:9,color:"#9CA3AF",overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{s.label}</div>
              </div>
            </div>
          ))}
        </div>

        {/* Tabs */}
        <div style={{display:"flex",gap:6,marginBottom:16,flexWrap:"wrap"}}>
          {[{id:"comptes",label:"👥 Comptes"},{id:"tontine",label:"🤝 Tontine"},{id:"filieres",label:"📚 Filières"},{id:"logs",label:"📊 Activité"}].map(t=>(
            <button key={t.id} onClick={()=>setTab(t.id)} style={{padding:"8px 14px",borderRadius:8,fontSize:12,fontWeight:700,cursor:"pointer",fontFamily:"inherit",background:tab===t.id?"#7C3AED":"#1A0A2E",color:tab===t.id?"white":"#9CA3AF",border:`1px solid ${tab===t.id?"#7C3AED":"#2D1B69"}`}}>{t.label}</button>
          ))}
          <Btn small color="#059669" onClick={openAdd}>+ Nouveau</Btn>
        </div>

        {/* Comptes */}
        {tab==="comptes" && (
          <div>
            {Object.keys(roleLabels).map(role=>{
              const usersInRole = allUsers.filter(u=>u.role===role);
              if (!usersInRole.length) return null;
              return (
                <div key={role} style={{marginBottom:16}}>
                  <div style={{fontSize:11,fontWeight:800,color:roleColors[role],textTransform:"uppercase",letterSpacing:2,marginBottom:8,borderBottom:"1px solid #2D1B69",paddingBottom:4}}>
                    {roleLabels[role]} ({usersInRole.length})
                  </div>
                  <div style={{display:"grid",gap:8}}>
                    {usersInRole.map(u=>(
                      <div key={u.id} style={{background:u.actif?"#0F0A1A":"#0A0808",border:`1px solid ${u.actif?"#2D1B69":"#3B1515"}`,borderRadius:10,padding:"11px 13px",boxSizing:"border-box",width:"100%",overflow:"hidden"}}>
                        <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:8}}>
                          <div style={{width:32,height:32,borderRadius:"50%",background:roleColors[u.role]+"33",display:"flex",alignItems:"center",justifyContent:"center",fontSize:15,flexShrink:0}}>
                            {role==="direction"?"🏛️":role==="enseignant"?"👨‍🏫":role==="eleve"?"🎓":role==="parent"?"👪":role==="secretaire"?"📋":"👔"}
                          </div>
                          <div style={{flex:1,minWidth:0}}>
                            <div style={{fontWeight:700,color:u.actif?"white":"#6B7280",fontSize:13,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{u.nom}</div>
                            <div style={{fontSize:10,color:"#6B7280"}}>@{u.login} • 🔑 {u.password}</div>
                          </div>
                          <span style={{padding:"2px 7px",borderRadius:20,fontSize:9,fontWeight:700,background:u.actif?"#05603A22":"#7F100022",color:u.actif?"#059669":"#DC2626",border:`1px solid ${u.actif?"#05603A44":"#7F100044"}`,flexShrink:0}}>{u.actif?"Actif":"Bloqué"}</span>
                        </div>
                        <div style={{display:"flex",gap:6,flexWrap:"wrap"}}>
                          <button onClick={()=>openEdit(u)} style={{padding:"6px 10px",background:"#1E3A5F",border:"1px solid #2563EB",color:"#93C5FD",borderRadius:7,fontSize:11,cursor:"pointer",fontWeight:700,flex:"1 1 auto"}}>✏️ Modifier</button>
                          <button onClick={()=>toggle(u.id)} style={{padding:"6px 10px",background:u.actif?"#3B0A0A":"#052E16",border:`1px solid ${u.actif?"#DC2626":"#059669"}`,color:u.actif?"#FCA5A5":"#6EE7B7",borderRadius:7,fontSize:11,cursor:"pointer",fontWeight:700,flex:"1 1 auto"}}>{u.actif?"🚫 Bloquer":"✅ Activer"}</button>
                          <button onClick={()=>resetPwd(u.id)} style={{padding:"6px 10px",background:"#1C1A00",border:"1px solid #D97706",color:"#FCD34D",borderRadius:7,fontSize:11,cursor:"pointer",fontWeight:700,flex:"1 1 auto"}}>🔑 Mdp</button>
                          <button onClick={()=>setConfirm(u)} style={{padding:"6px 10px",background:"#2D0000",border:"1px solid #DC2626",color:"#FCA5A5",borderRadius:7,fontSize:11,cursor:"pointer",fontWeight:700}}>🗑️</button>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              );
            })}
          </div>
        )}

        {tab==="tontine" && (
          <div style={{background:"#F7F8FA",borderRadius:14,padding:"14px",boxSizing:"border-box",width:"100%",overflow:"hidden"}}>
            <ModTontine data={data} setData={setData} currentUser={{nom:"Administrateur Système",role:"admin"}} canEdit={true} />
          </div>
        )}

        {tab==="filieres" && (
          <div style={{display:"grid",gap:10}}>
            {(data.filieres||[]).map(f=>(
              <div key={f.id} style={{background:"#0F0A1A",border:"1px solid #2D1B69",borderRadius:11,padding:"13px 16px",display:"flex",alignItems:"center",gap:12}}>
                <div style={{flex:1}}>
                  <div style={{fontWeight:700,color:"white",fontSize:14}}>{f.nom}</div>
                  <div style={{fontSize:11,color:"#9CA3AF"}}>{f.niveau} • {f.heures}h/an</div>
                </div>
                <div style={{textAlign:"center"}}>
                  <div style={{fontWeight:900,fontSize:20,color:"#D97706"}}>{f.etudiants}</div>
                  <div style={{fontSize:10,color:"#9CA3AF"}}>élèves</div>
                </div>
              </div>
            ))}
          </div>
        )}

        {tab==="logs" && (
          <div style={{background:"#0F0A1A",border:"1px solid #2D1B69",borderRadius:12,padding:"16px"}}>
            <div style={{fontWeight:800,color:"white",marginBottom:14,fontSize:13}}>📊 Vue système</div>
            {[
              {label:"Notes enregistrées",value:(data.notes||[]).length,icon:"📝"},
              {label:"Absences",value:(data.absences||[]).length,icon:"📋"},
              {label:"Inscriptions en attente",value:(data.inscriptions||[]).filter(i=>i.status==="En attente").length,icon:"✍️"},
              {label:"Messages",value:(data.messages||[]).length,icon:"💬"},
              {label:"Cours planifiés",value:(data.cours||[]).length,icon:"📖"},
              {label:"Année active",value:(data.school_years||[]).find(y=>y.is_active)?.label||"—",icon:"⭐"},
            ].map((s,i)=>(
              <div key={i} style={{display:"flex",justifyContent:"space-between",padding:"9px 0",borderBottom:"1px solid #2D1B69",fontSize:13}}>
                <span style={{color:"#D1D5DB"}}>{s.icon} {s.label}</span>
                <span style={{fontWeight:800,color:"#C4B5FD"}}>{s.value}</span>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* MODALS */}
      {(modal==="add"||modal==="edit") && (
        <Modal title={modal==="add"?"Nouveau compte":"Modifier compte"} onClose={()=>setModal(null)}>
          <Inp label="Nom complet" value={form.nom||""} onChange={v=>setForm({...form,nom:v})} placeholder="Ex: M. Baldé Mamadou" />
          <Inp label="Poste" value={form.poste||""} onChange={v=>setForm({...form,poste:v})} placeholder="Ex: Enseignant technique" />
          <Inp label="Identifiant (login)" value={form.login||""} onChange={v=>setForm({...form,login:v})} placeholder="Ex: balde.m" />
          <Inp label="Mot de passe" value={form.password||""} onChange={v=>setForm({...form,password:v})} placeholder="Ex: Prof@2025" />
          <Sel label="Rôle" value={form.role||"enseignant"} onChange={v=>setForm({...form,role:v})} options={roleOpts} />
          <label style={{display:"flex",alignItems:"center",gap:8,color:C.text,fontSize:13,marginBottom:12,cursor:"pointer"}}>
            <input type="checkbox" checked={!!form.actif} onChange={e=>setForm({...form,actif:e.target.checked})} />
            Compte actif
          </label>
          <div style={{display:"flex",gap:8,marginTop:8}}>
            <Btn full color="#059669" onClick={save}>✅ Enregistrer</Btn>
            <Btn full danger onClick={()=>setModal(null)}>Annuler</Btn>
          </div>
        </Modal>
      )}

      {resetTarget && (
        <Modal title={`🔑 Réinitialiser — ${resetTarget.nom}`} onClose={()=>setResetTarget(null)}>
          <Inp label="Nouveau mot de passe" value={newPwdInput} onChange={setNewPwdInput} placeholder="Nouveau mot de passe" />
          <div style={{display:"flex",gap:8,marginTop:8}}>
            <Btn full color="#D97706" onClick={confirmResetPwd}>✅ Enregistrer</Btn>
            <Btn full danger onClick={()=>setResetTarget(null)}>Annuler</Btn>
          </div>
        </Modal>
      )}

      {confirm && (
        <Modal title="⚠️ Supprimer ce compte ?" onClose={()=>setConfirm(null)}>
          <div style={{padding:"12px 14px",background:"#3B0A0A",border:"1px solid #DC262644",borderRadius:8,marginBottom:14,color:"#FCA5A5",fontSize:13}}>
            Supprimer définitivement <strong>{confirm.nom}</strong> (@{confirm.login}) ?
          </div>
          <div style={{display:"flex",gap:8}}>
            <Btn full danger onClick={()=>del(confirm.id)}>🗑️ Supprimer</Btn>
            <Btn full color="#374151" onClick={()=>setConfirm(null)}>Annuler</Btn>
          </div>
        </Modal>
      )}
    </div>
  );
}

// ─── MAIN APP ─────────────────────────────────────────────────────────────────
function App() {
  const [data, setDataRaw] = useState(loadData);
  const [user, setUser] = useState(null);
  const [showInscription, setShowInscription] = useState(false);
  const [fbReady, setFbReady] = useState(!window.FB);

  // Chargement initial Firebase + abonnement temps réel
  useEffect(() => {
    if (!window.FB) {
      setFbReady(true);
      return;
    }

    let unsubscribe = null;
    let cancelled = false;

    window.FB.loadData()
      .then(d => {
        if (cancelled) return;

        if (d) {
          setDataRaw(d);
          try {
            localStorage.setItem("cfp_v12", JSON.stringify(d));
          } catch {}
        }

        unsubscribe = window.FB.initSync(newData => {
          if (!cancelled && newData) {
            setDataRaw(newData);
            try {
              localStorage.setItem("cfp_v12", JSON.stringify(newData));
            } catch {}
          }
        });

        setFbReady(true);
      })
      .catch(e => {
        console.warn("Firebase loadData échoué — mode local", e);
        if (!cancelled) setFbReady(true);
      });

    return () => {
      cancelled = true;
      if (typeof unsubscribe === "function") unsubscribe();
    };
  }, []);

  const setData = d => { setDataRaw(d); saveData(d); };

  // ── Écran de chargement Firebase ─────────────────────────────────────────
  if (!fbReady) return (
    <div style={{minHeight:"100vh",display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",background:`linear-gradient(135deg,${C.navy} 0%,#2C5282 100%)`,gap:18}}>
      <img src={`data:image/png;base64,${LOGO_B64}`} alt="CFP Lambanyi" style={{height:100,borderRadius:12,boxShadow:"0 8px 30px rgba(0,0,0,0.3)"}} />
      <div style={{color:"#fff",fontSize:16,fontWeight:700}}>Connexion à la base de données…</div>
      <div style={{width:200,height:4,background:"rgba(255,255,255,0.2)",borderRadius:4,overflow:"hidden"}}>
        <div style={{width:"60%",height:"100%",background:C.gold,borderRadius:4,animation:"cfpPulse 1.2s ease-in-out infinite"}} />
      </div>
      <style>{"@keyframes cfpPulse{0%,100%{opacity:.4}50%{opacity:1}}"}</style>
    </div>
  );

  if (showInscription) return <InscriptionPublique data={data} setData={setData} onBack={()=>setShowInscription(false)} />;
  if (!user) return <Login onLogin={setUser} users={data.users} onInscription={()=>setShowInscription(true)} onResetPassword={(id, newPw) => setData({...data, users: data.users.map(u => u.id===id ? {...u, password:newPw} : u)})} />;
  if (user.role === "admin") return <EspaceAdmin data={data} setData={setData} onLogout={()=>setUser(null)} />;

  window.__cfpLogout = () => {
    if (window.FB) window.FB.logout();
    setUser(null);
  };
  // SyncBadge accessible depuis tous les espaces
  window.SyncBadge = window.FB ? window.FB.SyncBadge : null;

  // ── Bouton Retour Android ──────────────────────────────────────────────────
  // Géré via popstate : chaque changement de tab a été pushé dans history.
  // On dispatch l'événement "cfp:back:<space>" vers l'espace actif.
  useEffect(() => {
    // Entrée initiale dans history (sinon le premier popstate n'a pas d'état précédent)
    const spaceMap = {
      direction: "direction", directeur_etudes: "staff", charge_stages: "staff",
      charge_travaux: "staff", charge_finances: "staff", conseiller: "staff",
      secretaire: "staff", enseignant: "staff",
      eleve: "eleve", parent: "parent", admin: "admin",
    };

    let backPressedAt = 0; // timestamp du premier appui retour sur dashboard
    let toastTimeout  = null;

    const onPopState = (e) => {
      const st = e.state;
      // Pas d'état → on est revenu avant l'entrée initiale = écran principal
      const space = user ? spaceMap[user.role] : null;

      if (!st || !st.tab) {
        // On est sur l'écran principal (dashboard / premier tab)
        const now = Date.now();
        if (now - backPressedAt < 2000) {
          // Deuxième appui en moins de 2s → quitter
          clearTimeout(toastTimeout);
          window.__cfpHideExitToast && window.__cfpHideExitToast();
          window.history.go(-1); // laisse le navigateur/Android fermer l'app
          return;
        }
        // Premier appui → afficher le toast "Appuyez encore pour quitter"
        backPressedAt = now;
        window.__cfpShowExitToast && window.__cfpShowExitToast();
        toastTimeout = setTimeout(() => {
          backPressedAt = 0;
          window.__cfpHideExitToast && window.__cfpHideExitToast();
        }, 2000);
        // Re-pousser l'état pour que le prochain popstate soit capturé
        window.history.pushState({ space, tab: st?.tab || "dashboard" }, "", window.location.pathname);
        return;
      }

      // Il reste des états dans la pile → naviguer en arrière dans l'espace
      if (space) {
        window.dispatchEvent(new CustomEvent("cfp:back:" + space, { detail: { tab: st.tab } }));
      }
    };

    window.addEventListener("popstate", onPopState);
    return () => {
      window.removeEventListener("popstate", onPopState);
      clearTimeout(toastTimeout);
    };
  }, [user]);

  const staffRoles = ["directeur_etudes","charge_stages","charge_travaux","charge_finances","conseiller","secretaire"];

  // ── Toast "Appuyez encore pour quitter" ───────────────────────────────────
  const [showExitToast, setShowExitToast] = useState(false);
  window.__cfpShowExitToast = () => setShowExitToast(true);
  window.__cfpHideExitToast = () => setShowExitToast(false);

  return (
    <div style={{minHeight:"100vh",background:C.bg,fontFamily:"'Segoe UI',Tahoma,sans-serif",overflowX:"hidden"}}>
      {/* Toast bouton retour Android */}
      {showExitToast && (
        <div style={{
          position:"fixed", bottom:32, left:"50%", transform:"translateX(-50%)",
          background:"rgba(0,0,0,0.82)", color:"#fff",
          padding:"12px 24px", borderRadius:24,
          fontSize:14, fontWeight:600, zIndex:99999,
          boxShadow:"0 4px 20px rgba(0,0,0,0.4)",
          pointerEvents:"none", whiteSpace:"nowrap"
        }}>
          Appuyez encore une fois pour quitter
        </div>
      )}
      {user.role==="direction"&&<EspaceDirection data={data} setData={setData} user={user} />}
      {(staffRoles.includes(user.role)||user.role==="enseignant")&&<EspaceStaff data={data} setData={setData} user={user} />}
      {user.role==="eleve"&&<EspaceEleve data={data} user={user} activeYear={(data.school_years||[]).find(y=>y.is_active)} />}
      {user.role==="parent"&&<EspaceParent data={data} setData={setData} user={user} activeYear={(data.school_years||[]).find(y=>y.is_active)} />}
    </div>
  );
}

// Rendu de l application
const rootEl = document.getElementById("root");
if (rootEl) {
  ReactDOM.createRoot ? ReactDOM.createRoot(rootEl).render(React.createElement(App)) : ReactDOM.render(React.createElement(App), rootEl);
}
